class Workflow:
    def __init__(self):
        self.schedule = []
        self.events = {}
        self.log = []

    def every(self, label, func):
        self.schedule.append((label, func))
        return self

    def on(self, event, handler):
        self.events.setdefault(event, []).append(handler)
        return self

    def trigger(self, event, data=None):
        for handler in self.events.get(event, []):
            handler(data)

    def run_schedule(self):
        for label, func in self.schedule:
            result = func()
            self.log.append(label + ': 실행')
            if result:
                self.trigger(result)

def collect_news():
    print('[수집] AI 뉴스 3건 수집')
    return 'news_ready'

def analyze(data):
    print('[분석] 수집 완료 → 분석 시작')

def notify(data):
    print('[알림] 분석 완료 알림 발송')

wf = Workflow()
wf.every('매일 수집', collect_news).on('news_ready', analyze).on('news_ready', notify)
wf.run_schedule()
print('로그: ' + str(wf.log))
```

